"""Local B1 fix receipts; read-only Git metadata, no runtime/model operation."""
import hashlib,json,platform,subprocess,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];OUT=Path(__file__).resolve().parent
BASE=ROOT/'semantic_pallet_planner/outputs';PARENT=BASE/'JEV_JM2_B1_LIMITED_20261115_01';QA=BASE/'JEV_JM2_B1_LIMITED_QA_20261115_01'
PKG=ROOT/'semantic_pallet_planner/src/semantic_pallet_planner'
REPORT='docs/03_阶段产出分析/Jev/Jev_JM2-B1拒绝门与审核绑定最小整改验收_20261115_01.md'
def read(p):return json.loads(p.read_text())
def write(n,v):(OUT/n).write_text(json.dumps(v,ensure_ascii=False,sort_keys=True,indent=2)+'\n')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def entry(p):return dict(path=p.relative_to(ROOT).as_posix(),bytes=p.stat().st_size,sha256=sha(p))
def git(*a):return subprocess.check_output(['git',*a],cwd=ROOT,text=True).strip()
def main():
 head=git('rev-parse','HEAD');assert head=='e2d585ddffa008a17d2fb8219d16c6c39ca26a2c'
 for c in ['e2d585dd','6be30b182ab75e6593b17cc8dbfcdbfc69900c94']:subprocess.check_call(['git','merge-base','--is-ancestor',c,'HEAD'],cwd=ROOT)
 result=read(OUT/'focused_results.json');assert len(result['cases'])==51 and not result['unexpected_exceptions']
 old=read(PARENT/'source_manifest.json');source={n:sha(PKG/n) for n in old};changes={n:dict(before=d,after=source[n]) for n,d in old.items() if source[n]!=d}
 assert set(changes)=={'jev_select/packaging_experience_contract.py','jev_select/packaging_versions.py'}
 for n in changes:assert sha(OUT/'entry_source_bytes'/Path(n).name)==old[n]
 write('source_manifest.json',source)
 write('source_identity.json',dict(version='jm2_b1_fix_source_identity_v1',actual_head=head,reviewed_development='6be30b182ab75e6593b17cc8dbfcdbfc69900c94',new_validation_revision='jev_jm_e_validation_v2',source_digest=hashlib.sha256(json.dumps(source,sort_keys=True,separators=(',',':')).encode()).hexdigest(),files=len(source),source_manifest=entry(OUT/'source_manifest.json'),changed_files=changes,all_three_jm_e_schemas_unchanged=True,central_contracts_unchanged=True,historical_identity_resigned=False,python=sys.version,platform=platform.platform(),environment=entry(OUT/'import_review.json'),recovery='New validation source is a new identity, not an exemption for old frozen execution'))
 write('entry_identity.json',dict(root=str(ROOT),branch=git('branch','--show-current'),upstream=git('rev-parse','--abbrev-ref','--symbolic-full-name','@{upstream}'),initial_head='6be30b182ab75e6593b17cc8dbfcdbfc69900c94',actual_head=head,QA_commit_contained=True,initial_workspace='CLEAN',pull='fast-forward; initial sandbox FETCH_HEAD read-only; authorized escalation succeeded',stash_reset_force_push=False,stage_commit_push='NOT_PERFORMED',SKILL='EXCLUDED_ENTIRE_TREE'))
 write('compatibility_receipt.json',dict(version='jm2_b1_validation_compatibility_v1',revision='jev_jm_e_validation_v2',wire_versions='v1 unchanged',schemas='all three original closed schemas unchanged',valid_saved_archives='5 original real packs validate without reseal; original synthetic positive remains structural only',strictness='invalid semantic objects, wrong card/source or mixed distinctions now rejected for v1 documents',real_binding='card_ref equals canonical case-bearing first evidence source, card_index matches pointer, exact JSON digest of source case matches pack; declared content_assessment_source equals review_source_ref',fixture_binding='existing named /case,/review,/review_source sections within same synthetic source document; no new approval/signature fields',historical_validation='old archived outcomes retained as historical; no fallback to vulnerable revision and no old identity resigned',scope='bug-fix revision only, not B2 lifecycle or real approval'))
 closures=[]
 for issue,scope in [('QA-JM2B1-01','semantic type/required field validation before .get; nested input guards; no enlarged except'),('QA-JM2B1-02','exact case/source identity and synthetic document binding'),('QA-JM2B1-03','nonempty subset of changed attributes; mixed changed/unchanged rejected')]:
  closures.append(dict(id=issue,status='PASS_LOCAL_REMEDIATION_PENDING_INDEPENDENT_QA',scope=scope,evidence=dict(path=(OUT/'focused_results.json').relative_to(ROOT).as_posix(),sha256=sha(OUT/'focused_results.json'),pointer='/cases'),cases=[r['name'] for r in result['cases'] if r['issue']==issue]))
 write('issue_closure.json',dict(version='jm2_b1_fix_issue_closure_v1',original_quality_review=entry(QA/'quality_review.json'),original_probe_results=entry(QA/'probe_results.json'),original_failures_retained=True,issues=closures))
 write('acceptance.json',dict(version='jm2_b1_fix_acceptance_v1',items=[dict(id='M22-01',status='PASS',scope='minimal rejection/type/binding revision only; no complete B1 closure'),dict(id='M22-03',status='PARTIAL',source_binding_and_distinction_structure='PASS_LOCAL_FIX',trusted_real_content='PENDING_NOT_RUN'),dict(id='M22-07',status='PARTIAL',real_content='NOT_RUN',synthetic_expression='STRUCTURE_VALID_CONTENT_PENDING')],full_B1_exit='NOT_CLOSED',next_stage_admission='NOT_READY',return_to='INDEPENDENT_QA'))
 parent=read(PARENT/'experience_generation_readiness.json')
 write('experience_generation_readiness.json',dict(version='jm2_b1_fix_readiness_v1',engineering_status='COMPLETE_MINIMAL_REMEDIATION_PENDING_QA',evidence_readiness='SUFFICIENT_FOR_FIX_QA_NOT_GENERATION',research_result='NOT_ESTABLISHED',next_stage_admission='NOT_READY',return_to='INDEPENDENT_QA',real_material_status='NOT_READY',qualified_real_cards=0,archive_only_real_cards=5,pending_trusted_approval=5,all_generation_and_execution_permissions=False,qualified_generation_input=False,execution_eligible=False,full_B1_exit='NOT_CLOSED',B2_C='NOT_GRANTED',M21_07='PARTIAL_INHERITED',M22_03='PARTIAL',M22_07='PARTIAL_REAL_CONTENT_NOT_RUN',boundaries=parent['boundaries'],historical_requests57_commits75='HISTORICAL_NOT_CURRENT',actual_operations=result['actual_operations']))
 write('check_attempts.json',dict(version='jm2_b1_fix_attempts_v1',current=[dict(check='focused compatibility/negative matrix',status='PASS_51',log='check_attempt_01.log')],historical_failures=[entry(QA/'quality_review.json'),entry(QA/'probe_results.json'),entry(QA/'static_checks.json')],unchanged_parent_outcomes='QA blocking findings and PARTIAL remain in original files; new issue_closure references them',not_run=['model/content approval','orders/forks/candidate rebuild/prefix replay/LP','full B1/B2/C','historical frozen execution'],tool_read_attempt='Initial shell batch additionally requested nonexistent probe_contract.json; corrected to read existing probe_contract.py; no historical file changed'))
 write('handoff.json',dict(version='jm2_b1_fix_handoff_v1',date='2026-11-16',started_date='2026-11-15',actual_head=head,unit='JM2-B1 minimal remediation only',parent_QA=entry(QA/'handoff.json'),parent_development=entry(PARENT/'handoff.json'),report=REPORT,issues='issue_closure.json',acceptance='acceptance.json',readiness='experience_generation_readiness.json',tests='focused_results.json',compatibility='compatibility_receipt.json',source='source_identity.json',validation_contract='validation_contract.json',failures='check_attempts.json',manifest='delivery_manifest.json',engineering_status='COMPLETE_MINIMAL_REMEDIATION_PENDING_QA',evidence_readiness='SUFFICIENT_FOR_FIX_QA_NOT_GENERATION',research_result='NOT_ESTABLISHED',next_stage_admission='NOT_READY',return_to='INDEPENDENT_QA',actual_operations=result['actual_operations'],stop=True,stop_reason='整改后交回独立质检；不批准真实卡、不生成、不推进B2/C、不编写下一任务提示词'))
 paths=[p for p in OUT.rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.name!='delivery_manifest.json']+[PKG/n for n in changes]+[ROOT/REPORT]
 write('delivery_manifest.json',dict(version='jm2_b1_fix_manifest_v1',self_hash_excluded=True,excluded=['SKILL/ entire tree','shared README navigation','__pycache__'],files=[entry(p) for p in sorted(paths)]))
 print('FINALIZED_MINIMAL_FIX',len(paths),'NEXT_STAGE_NOT_READY')
if __name__=='__main__':main()
